INSERT INTO categories (name, slug, description, display_order) SELECT 'Catering', 'catering', 'Party trays and traditional dishes for events and gatherings', COALESCE(MAX(display_order), 0) + 1 FROM categories WHERE NOT EXISTS (SELECT 1 FROM categories WHERE slug = 'catering');
INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Master of Social Work Graduation Cake', 'master-of-social-work-graduation-cake', 'A two-tier white graduation cake designed around a "Master of Social Work" book, with a graduate silhouette, mortarboard topper, gold leaf and pearl accents. Made to celebrate a hard-earned master''s degree.', 0, 'USD', 1, '/media/images/cakes/master-of-social-work-graduation-cake-01.jpg', 'images/cakes/master-of-social-work-graduation-cake-01.jpg', 1, 1, 0);
INSERT INTO cake_images (cake_id, image_url, image_key, media_type, poster_url, poster_key, display_order) VALUES ((SELECT id FROM cakes WHERE slug = 'master-of-social-work-graduation-cake'), '/media/videos/cakes/master-of-social-work-graduation-cake-v01.mp4', 'videos/cakes/master-of-social-work-graduation-cake-v01.mp4', 'video', '/media/images/cakes/master-of-social-work-graduation-cake-v01-poster.jpg', 'images/cakes/master-of-social-work-graduation-cake-v01-poster.jpg', 0);
INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('White Floral Two-Tier Birthday Cake', 'white-floral-two-tier-birthday-cake', 'An elegant two-tier white birthday cake with textured icing, rhinestone ribbon bands, a cascade of ivory sugar roses and a silver "Happy Birthday" topper, finished with a gold personalised name on the board.', 0, 'USD', 1, '/media/images/cakes/white-floral-two-tier-birthday-cake-01.jpg', 'images/cakes/white-floral-two-tier-birthday-cake-01.jpg', 1, 1, 0);
INSERT INTO cake_images (cake_id, image_url, image_key, media_type, poster_url, poster_key, display_order) VALUES ((SELECT id FROM cakes WHERE slug = 'white-floral-two-tier-birthday-cake'), '/media/videos/cakes/white-floral-two-tier-birthday-cake-v01.mp4', 'videos/cakes/white-floral-two-tier-birthday-cake-v01.mp4', 'video', '/media/images/cakes/white-floral-two-tier-birthday-cake-v01-poster.jpg', 'images/cakes/white-floral-two-tier-birthday-cake-v01-poster.jpg', 0);
INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Scotch Eggs', 'scotch-eggs', 'Whole boiled eggs wrapped in seasoned meat, breaded and fried golden. A filling favourite for small chops platters and party trays.', 0, 'USD', 5, '/media/images/cakes/scotch-eggs-01.jpg', 'images/cakes/scotch-eggs-01.jpg', 0, 1, 0);
