INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Vegetable Soup & Fufu', 'vegetable-soup-and-fufu', 'A rich leafy vegetable soup cooked with assorted meat and fish, served with freshly wrapped fufu. Available in trays for parties and family gatherings.', 0, 'USD', (SELECT id FROM categories WHERE slug = 'catering'), '/media/images/cakes/vegetable-soup-and-fufu-01.jpg', 'images/cakes/vegetable-soup-and-fufu-01.jpg', 0, 1, 0);
