INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Fish Stew', 'fish-stew', 'Fried fish simmered in a well-seasoned tomato and pepper stew with carrots and onions. Ordered by the tray for events.', 0, 'USD', (SELECT id FROM categories WHERE slug = 'catering'), '/media/images/cakes/fish-stew-01.jpg', 'images/cakes/fish-stew-01.jpg', 0, 1, 0);
