INSERT INTO cakes (name, slug, description, price_cents, currency, category_id, image_url, image_key, is_featured, is_available, display_order) VALUES ('Event Catering', 'event-catering', 'Full buffet catering for your event, served in gold chafing dishes: rice, stir-fried vegetables, grilled fish, peppered meat and more. Message us with your guest count and menu ideas for a quote.', 0, 'USD', (SELECT id FROM categories WHERE slug = 'catering'), '/media/images/cakes/event-catering-01.jpg', 'images/cakes/event-catering-01.jpg', 0, 1, 0);
